        h.mark(c, &mut lb, Mark { pts: &[(-0.085, 0.83 - drop), (-0.045, 0.857 - drop), (0.0, 0.862 - drop)], pressure: (0.4, 0.2), ramps: (0.2, 0.5) }, None);
        let mut ld = h.take(Tool::round_sable, 0.012, lean(mix(g.dress, l, 0.4)), 0.3 * 0.4);
