            width_um: None,
            depth_um: 20.0,
            cupping_um: 15.0,
            dirt: 0.4,
            corners: true,
            vary: 1.0,
            veil: 0.5,
            hierarchy: 1.0,
            patchy: 1.0,
            grain: 0.15,
            grime: 1.0,
            seed,
        }
    }

    /// The Round 6 recipe: one even network (every crack alike, no patchy
    /// development, no direction, the old soot in the cracks), fitted to
    /// the canvas like `aged`.
    pub fn even(seed: u64) -> Self {
        Cracks { hierarchy: 0.0, patchy: 0.0, grain: 0.0, grime: 0.0, ..Cracks::aged(seed) }
    }

    /// The recipe fitted to a canvas primed with `ground_um` µm: every
    /// `None` field filled in.
    pub fn fit(&self, ground_um: f32) -> Cracks {
        let ground = self.ground_um.unwrap_or(ground_um);
        let island = self.island_mm.unwrap_or_else(|| island_for(ground));
        Cracks { ground_um: Some(ground), island_mm: Some(island), width_um: Some(self.width_um.unwrap_or(STRAIN * island * 1000.0)), ..*self }
    }

    /// Ground thickness, µm (0 if not given yet).
    pub fn ground(&self) -> f32 {
        self.ground_um.unwrap_or(0.0)
    }

    /// Median island size, mm.
    pub fn island(&self) -> f32 {
        self.island_mm.unwrap_or_else(|| island_for(self.ground()))
    }

    /// Opening of a primary crack, µm.
    pub fn width(&self) -> f32 {
        self.width_um.unwrap_or(STRAIN * self.island() * 1000.0)
    }

    /// Weave-coupling weight w = clamp(1 − t_ground / 100 µm).
    pub fn weave(&self) -> f32 {
        (1.0 - self.ground() / 100.0).clamp(0.0, 1.0)
    }

    /// Soft pointed round: smooth, precise, little ploughing. Friedrich's detail brush.
    pub fn round_sable(width: f32) -> Self {
        Tool { stiffness: 0.2, pickup: 0.1, push: 0.05, splay: 0.45, ragged: 0.15, ..Self::base(Kind::Round, width) }
    }

    /// Stiff hog-bristle flat: square marks, strong ridges, broken edges.
    pub fn hog_flat(width: f32) -> Self {
        Tool {
            bristles: 140,
            length: width * 0.5,
            stiffness: 0.85,
            hair: 1.1,
            run: 25.0 + 4.0 * width,
            lay: 1.4,
            pickup: 0.2,
            push: 0.3,
            splay: 0.12,
            ragged: 0.45,
            ..Self::base(Kind::Flat, width)
        }
    }

    /// Filbert: oval hog/synthetic, soft-ended marks, good for blending forms.
    pub fn filbert(width: f32) -> Self {
        Tool { bristles: 120, stiffness: 0.6, lay: 1.2, pickup: 0.18, push: 0.18, ragged: 0.3, ..Self::base(Kind::Filbert, width) }
    }

    /// Fan: sparse spread bristles, for foliage, grasses and feathering.
    pub fn fan(width: f32) -> Self {
        Tool { bristles: 36, hair: 0.6, stiffness: 0.5, lay: 0.7, pickup: 0.1, push: 0.08, splay: 0.2, ragged: 0.5, ..Self::base(Kind::Fan, width) }
    }

    /// Rigger / liner: a few very long soft hairs. Twigs, rigging, fine lines.
    pub fn rigger(width: f32) -> Self {
        Tool {
            bristles: 14,
            length: width * 5.0,
            stiffness: 0.08,
            hair: 1.4,
            run: 250.0,
            lay: 1.0,
            pickup: 0.04,
            push: 0.02,
            splay: 0.6,
            ragged: 0.1,
            ..Self::base(Kind::Rigger, width)
        }
    }

    /// Badger blender: big, soft, used clean to fuse wet paint.
    pub fn badger(width: f32) -> Self {
        Tool {
            bristles: 160,
            length: width * 0.6,
            stiffness: 0.15,
            lay: 0.0,
            run: 30.0,
            pickup: 0.3,
            push: 0.04,
            splay: 0.5,
            ragged: 0.2,
            ..Self::base(Kind::Blender, width)
        }
    }

    /// Small soft round for stippling: a short, full, blunt-pointed tuft of
    /// soft hair (sable or fitch) used with the tip, touch after touch. Few
    /// modeled hairs (a pressed tip is one patch; see `Touch`), little
    /// ploughing, moderate pickup so touches into wet paint fuse.
    pub fn stippler(width: f32) -> Self {
        Tool {
            bristles: 36,
            length: width * 0.8,
            stiffness: 0.3,
            hair: 1.2,
            lay: 0.9,
            pickup: 0.12,
            push: 0.02,
            splay: 0.4,
            ragged: 0.2,
            ..Self::base(Kind::Round, width)
        }
    }

    /// Check that the tool describes a physically possible brush: finite
    /// parameters, a positive width, hair size and load run, at least one
    /// bristle, no negative length, lay, splay or raggedness, and stiffness,
    /// pickup and push within 0..1. The fields are public, so every painting
    /// entry point checks this (see `assert_valid`): the stroke footprints

