//! r14_p2: Evening over the flat country. The sun has just gone down behind
//! a small town on the far edge of a flat coastal plain; a lagoon under the
//! glow, meadows stepping down toward us, a dark rise with two figures seen
//! from behind, a young crescent above the afterglow.
//!
//!   cargo paint r14_p2 -- --full --width 2400
//!   cargo paint r14_p2 -- --full --width 2400 --crop 300,300,600,500

use paint::color::{Mix, gradient, mix};
use paint::{Fbm, Held, Mask, Pigment, Rgb, Rng, Stipple, Style, Tool, hex, shift, smoothstep};
use paintings::figures::{self, Gown, WomanPose};
use paintings::run::{Finish, Run};
use std::f32::consts::FRAC_PI_2;

const ASPECT: f32 = 1.4;
/// The horizon (units from the top).
const HZ: f32 = 468.0;
/// Where the sun went down (x), a little left of the town's middle.
const GX: f32 = 405.0;

/// The crescent: center and radius.
const MOON: (f32, f32, f32) = (655.0, 178.0, 8.5);

/// The look of the evening sky at a point: bands that wander a little,
/// warm and pale at the horizon under the glow, a greenish cream band,
/// then smalt gray-blue toward the top.
fn sky_at(n: &Fbm, x: f32, y: f32) -> Rgb {
    let t = ((HZ - y) / HZ).clamp(0.0, 1.0) + 0.03 * n.get(x * 0.5, y * 1.5) + 0.02 * n.get(x * 3.0 + 400.0, y * 0.5);
    let g = (-((x - GX) / 300.0).powi(2)).exp();
    let g2 = (-((x - GX) / 140.0).powi(2)).exp();
    let low = mix(hex("#d6c7ab"), hex("#efcf98"), g, Mix::Light);
    let low = mix(low, hex("#f3c98a"), g2 * 0.5, Mix::Light);
    let band = mix(hex("#d9d2b4"), hex("#ecdbaa"), g, Mix::Light);
    gradient(
        &[
            (0.0, low),
            (0.07, band),
            (0.2, mix(hex("#d7d6bd"), hex("#e2dbb8"), g, Mix::Light)),
            (0.36, hex("#c3c8c1")),
            (0.55, hex("#a4b0bd")),
            (0.78, hex("#8797ad")),
            (1.0, hex("#72819b")),
        ],
        t,
        Mix::Light,
    )
}

/// Low streaks of cloud over the glow: (alpha, how far down the streak).
/// Each streak is thin, long, ragged at its ends and a little bowed.
fn streaks(n: &Fbm, x: f32, y: f32) -> (f32, f32) {
    // (middle y, x from, x to, thickness)
    const S: [(f32, f32, f32, f32); 6] = [
        (441.0, 180.0, 560.0, 3.2),
        (428.0, 470.0, 760.0, 2.4),
        (404.0, 250.0, 420.0, 2.0),
        (392.0, 560.0, 900.0, 3.0),
        (360.0, 90.0, 360.0, 2.2),
        (318.0, 640.0, 820.0, 1.6),
    ];
    let mut a: f32 = 0.0;
    let mut low = 0.0;
    for (i, &(cy, x0, x1, th)) in S.iter().enumerate() {
        if x < x0 - 30.0 || x > x1 + 30.0 {
            continue;
        }
        let k = i as f32 * 97.0;
        let u = ((x - x0) / (x1 - x0)).clamp(0.0, 1.0);
        let taper = (smoothstep(0.0, 0.25, u) * (1.0 - smoothstep(0.7, 1.0, u))).powf(0.7);
        let rag = 0.5 + 0.5 * n.get(x * 1.8 + k, k);
        let thick = th * taper * (0.4 + 1.2 * rag);
        let mid = cy + 4.0 * n.get(x * 0.4 + k, 3.0 * k) + 2.0 * (u - 0.5).powi(2) * 4.0;
        let d = y - mid;
        if thick <= 0.05 {
            continue;
        }
        let v = 1.0 - smoothstep(thick * 0.5, thick * 1.4, d.abs());
        if v > a {
            a = v;
            low = (d / thick).clamp(-1.0, 1.0);
        }
    }
    (a, low)
}

/// The sky with its cloud streaks, as the painter wants it to look.
fn sky_look(n: &Fbm, x: f32, y: f32) -> Rgb {
    let base = sky_at(n, x, y);
    let (a, low) = streaks(n, x, y);
    if a <= 0.0 {
        return base;
    }
    let g = (-((x - GX) / 260.0).powi(2)).exp();
    // backlit: violet gray, the underside touched with the glow
    let body = mix(hex("#a79ea3"), hex("#9a8d95"), g, Mix::Light);
    let under = mix(body, hex("#e7b889"), smoothstep(0.0, 1.0, low) * (0.35 + 0.5 * g), Mix::Light);
    mix(base, under, a * 0.75, Mix::Light)
}

/// Houses and trees of the town: the height above the horizon of its
/// roofline at x (0 where there is no town).
fn town_h(x: f32) -> f32 {
    let mut h: f32 = 0.0;
    // row of roofs and tree crowns (x, half width, eave, ridge)
    const HOUSES: [(f32, f32, f32, f32); 22] = [
        (300.0, 6.0, 4.0, 7.0),
        (311.0, 5.0, 5.5, 9.0),
        (322.0, 7.0, 4.5, 8.0),
        (336.0, 6.0, 6.0, 11.5),
        (349.0, 4.5, 5.0, 8.5),
        (359.0, 6.5, 6.5, 10.0),
        (447.0, 5.0, 5.0, 9.5),
        (457.0, 6.0, 6.5, 11.0),
        (470.0, 5.0, 5.5, 8.0),
        (480.0, 4.0, 7.0, 10.5),
        (491.0, 6.0, 5.0, 9.0),
        (520.0, 5.5, 6.0, 10.0),
        (533.0, 7.0, 5.0, 8.5),
        (546.0, 5.0, 6.0, 9.5),
        (557.0, 6.0, 4.0, 7.0),
        (569.0, 5.0, 3.5, 6.0),
        (580.0, 4.0, 3.0, 5.0),
        (290.0, 5.0, 3.0, 5.0),
        (282.0, 4.0, 2.5, 4.0),
        (365.0, 4.0, 6.0, 9.0),
        (441.0, 4.0, 4.0, 8.0),
        (507.0, 4.0, 5.0, 8.0),
    ];
    for &(cx, hw, eave, ridge) in HOUSES.iter() {
        let d = (x - cx).abs();
        if d < hw {
            let r = eave + (ridge - eave) * (1.0 - d / hw);
            h = h.max(r);
        }
    }
    // tree crowns among the houses (rounded)
    const TREES: [(f32, f32, f32); 7] = [(305.0, 9.0, 13.0), (329.0, 7.0, 12.0), (463.0, 8.0, 14.0), (540.0, 10.0, 15.0), (575.0, 8.0, 10.0), (287.0, 6.0, 8.0), (497.0, 6.0, 11.0)];
    for &(cx, r, top) in TREES.iter() {
        let d = (x - cx) / r;
        if d.abs() < 1.0 {
            h = h.max(top * (1.0 - d * d).sqrt().powf(0.6));
        }
    }
    // the great church: nave with a steep roof, west tower, spire
    if (378.0..=432.0).contains(&x) {
        h = h.max(20.0 + 9.0 * (1.0 - ((x - 405.0) / 27.0).abs()));
    }
    // choir, lower, to the east
    if (432.0..=442.0).contains(&x) {
        h = h.max(17.0 + 4.0 * (1.0 - ((x - 437.0) / 5.0).abs()));
    }
    if (368.0..=381.0).contains(&x) {
        h = h.max(62.0);
    }
    // spire: from the tower top to a point, with a little broach
    let sd = (x - 374.5).abs();
    if sd < 6.5 {
        h = h.max(62.0 + 42.0 * (1.0 - sd / 6.5).powf(1.15));
    }
    // the second church: a square tower with a baroque cap and a lantern
    if (510.0..=522.0).contains(&x) {
        h = h.max(46.0);
    }
    let bd = (x - 516.0).abs();
    if bd < 7.0 {
        // bell-shaped cap
        h = h.max(46.0 + 8.0 * (1.0 - (bd / 7.0).powi(2)).max(0.0).sqrt());
    }
    if bd < 2.4 {
        h = h.max(60.0);
    }
    if bd < 0.9 {
        h = h.max(67.0);
    }
    if (522.0..=548.0).contains(&x) {
        h = h.max(16.0 + 6.0 * (1.0 - ((x - 535.0) / 13.0).abs()));
    }
    h
}

/// Far shore: low woods and scattered trees along the horizon, broken by
/// open stretches (height above the horizon).
fn shore_h(n: &Fbm, x: f32) -> f32 {
    let v = n.get(x * 0.9, 50.0);
    let woods = smoothstep(-0.1, 0.25, v) * (3.5 + 3.0 * (0.5 + 0.5 * n.get(x * 6.0, 7.0)));
    let near_town = if (250.0..620.0).contains(&x) { 1.0 } else { 0.0 };
    woods.max(near_town * 2.0) + 0.8
}

/// The lagoon: its near shore below the horizon (units below HZ) at x.
fn lagoon_w(n: &Fbm, x: f32) -> f32 {
    let w = 13.0 * (1.0 - smoothstep(60.0, 640.0, x)) + 2.0 * n.get(x * 1.2, 90.0);
    w.max(0.0)
}

/// The foreground rise: its crest y at x.
fn crest(n: &Fbm, x: f32) -> f32 {
    let u = x / 1000.0;
    let base = 650.0 - 150.0 * smoothstep(0.1, 0.8, u) + 35.0 * smoothstep(0.84, 1.05, u);
    base + 5.0 * n.get(x * 0.7, 20.0) + 1.5 * n.get(x * 4.0, 60.0)
}

fn main() {
    let o = Run::new("r14_p2");
    let st = Style::friedrich();
    let pal = &st.palette;
    let mut rng = Rng::new(o.seed);
    let mut c = o.canvas(|| st.prepare(o.width, ASPECT, o.seed));
    let f = c.frame();
    let h = f.height();
    let n = Fbm::new(7, 4, 300.0);
    let sky_pal = pal.only(&["lead white", "smalt", "pale smalt", "cobalt blue", "yellow ochre", "chrome yellow", "vermilion", "red earth", "raw umber"]);
    let sky = Mask::from_fn(f, |_, y| 1.0 - smoothstep(HZ + 6.0, HZ + 10.0, y));

    if o.stage("sky", &mut c, &mut rng) {
        // lay-in: thin, long, nearly level arcs; the streaks are in the
        // color the brush carries, laid into the same wet paint
        let hd = st.broad().palette(&sky_pal).color(|x, y| sky_look(&n, x, y)).angle(|_, _| 0.0).angle_jitter(0.05).length(60.0, 200.0).coverage(3.8).medium(0.4).clip(true);
        c.work(&sky, &hd, 11);
        let hd = st.broad().palette(&sky_pal).color(|x, y| sky_look(&n, x, y)).angle(|_, _| 0.0).cross(0.12).length(40.0, 140.0).coverage(1.6).medium(0.45).clip(true);
        c.work(&sky, &hd, 12);
        if let Some(b) = st.blend() {
            c.work(&sky, &b.angle(|_, _| 0.0).angle_jitter(0.1), 13);
        }
        // stipple into the wet: each dip moves a little from what is there
        // toward the sky wanted (never a fixed mix)
        let sp = Stipple::new(Tool::stippler(3.0))
            .mixed(&sky_pal, 0.45)
            .color_over(|x, y, u| mix(u, sky_look(&n, x, y), 0.45, Mix::Light))
            .coverage(|_, _| 1.8)
            .pressure(0.45, 0.8)
            .dips(18, 0.4, 0.5)
            .cluster(0.3, None)
            .clip(true);
        c.stipple(&sky, &sp, 14);
        c.dry();
        // once dry: a finer stipple barely lighter than the field, denser
        // toward the glow
        let sp = Stipple::new(Tool::stippler(1.7))
            .mixed(&sky_pal, 0.5)
            .color_over(|_, _, u| shift(u, 0.012, 0.0, 0.002))
            .coverage(|x, y| 0.5 + 1.3 * smoothstep(120.0, HZ, y) * (0.4 + 0.6 * (-((x - GX) / 320.0).powi(2)).exp()))
            .pressure(0.4, 0.75)
            .dips(22, 0.35, 0.6)
            .cluster(0.35, None)
            .clip(true);
        c.stipple(&sky, &sp, 15);
        c.dry();
    }

    // ---- the young moon: lit limb toward where the sun went down
    let (mx, my, mr) = MOON;
    let (sx, sy) = (GX - mx, HZ + 80.0 - my);
    let sl = (sx * sx + sy * sy).sqrt();
    let (ux, uy) = (sx / sl, sy / sl);
    let crescent = Mask::from_fn(f, move |x, y| {
        let d0 = ((x - mx).powi(2) + (y - my).powi(2)).sqrt();
        let (dx, dy) = (x - (mx - ux * mr * 0.42), y - (my - uy * mr * 0.42));
        let d1 = (dx * dx + dy * dy).sqrt();
        (1.0 - smoothstep(mr - 0.6, mr + 0.4, d0)) * smoothstep(mr * 0.98 - 0.5, mr * 0.98 + 0.5, d1)
    });
    if o.stage("moon", &mut c, &mut rng) {
        let hd = st
            .detail()
            .tool(Tool::round_sable(1.5))
            .color(|_, _| hex("#f2ead0"))
            .angle(move |x, y| (y - my).atan2(x - mx) + FRAC_PI_2)
            .angle_jitter(0.15)
            .length(3.0, 9.0)
            .coverage(3.0)
            .pressure(0.55, 0.8)
            .clip(true);
        c.work(&crescent, &hd, 21);
        c.dry();
    }

    // ---- far shore and the town on it
    let town = Mask::from_fn(f, |x, y| {
        let th = town_h(x);
        if th <= 0.0 {
            return 0.0;
        }
        smoothstep(HZ - th - 0.4, HZ - th + 0.4, y) * (1.0 - smoothstep(HZ + 3.0, HZ + 4.0, y))
    });
    let shore = Mask::from_fn(f, |x, y| smoothstep(HZ - shore_h(&n, x) - 0.6, HZ - shore_h(&n, x) + 0.6, y) * (1.0 - smoothstep(HZ + 3.0, HZ + 4.0, y)));
    if o.stage("far", &mut c, &mut rng) {
        // the far shore: a pale blue-gray, barely darker than the glow
        let hd = st
            .hatch()
            .color(|x, y| mix(hex("#a39d9d"), hex("#b4a59a"), (-((x - GX) / 250.0).powi(2)).exp(), Mix::Light).map(|v| v * (0.94 + 0.06 * smoothstep(HZ - 8.0, HZ, y))))
            .angle(|_, _| 1.45)
            .angle_jitter(0.3)
            .length(2.0, 6.0)
            .coverage(3.0)
            .clip(true);
        c.work(&shore, &hd, 31);
        c.dry();
        // the town: backlit, cool, one flat dark; mist lies at its foot
        let hd = st
            .detail()
            .tool(Tool::round_sable(1.6))
            .color(|x, y| {
                let mist = smoothstep(HZ - 12.0, HZ, y);
                mix(hex("#6b6875"), hex("#8f8a8c"), mist * 0.7 + 0.1 * (-((x - GX) / 120.0).powi(2)).exp(), Mix::Light)
            })
            .angle(|x, y| if town_h(x) > 25.0 && y < HZ - 20.0 { FRAC_PI_2 } else { 0.1 })
            .angle_jitter(0.12)
            .length(2.5, 8.0)
            .coverage(3.2)
            .clip(true);
        c.work(&town, &hd, 32);
        c.dry();
    }

    // ---- the lagoon under the glow: it gives back the sky, a little darker
    let lagoon = Mask::from_fn(f, |x, y| {
        let w = lagoon_w(&n, x);
        if w <= 0.2 {
            return 0.0;
        }
        smoothstep(HZ + 1.5, HZ + 2.5, y) * (1.0 - smoothstep(HZ + w - 0.6, HZ + w + 0.6, y))
    });
    let water_look = move |x: f32, y: f32| {
        let d = (y - HZ).max(0.0);
        let s = sky_at(&n, x, HZ - 6.0 - d * 3.0);
        let th = town_h(x);
        let refl = if th > 0.0 && d < th * 0.8 { 0.55 * (1.0 - d / (th * 0.8)) } else { 0.0 };
        let s = mix(s, hex("#7a7480"), refl, Mix::Light);
        shift(s, -0.05 - 0.01 * d, 0.0, -0.01)
    };
    if o.stage("water", &mut c, &mut rng) {
        let hd = st.body().color(water_look).angle(|_, _| 0.0).angle_jitter(0.02).curve(0.01, 0.0).length(20.0, 70.0).coverage(3.2).clip(true);
        c.work(&lagoon, &hd, 41);
        if let Some(b) = st.blend() {
            c.work(&lagoon, &b.tool(Tool { pickup: 0.15, run: 45.0, ..Tool::badger(12.0) }).angle(|_, _| 0.0).angle_jitter(0.01).length(40.0, 120.0), 42);
        }
        c.dry();
    }

    // ---- the meadows: value steps toward us, level strokes, larger near
    let land = Mask::from_fn(f, |x, y| smoothstep(HZ + 1.0, HZ + 2.5, y) * (1.0 - lagoon.sample(x, y)));
    let land_look = move |x: f32, y: f32| {
        let d = (y - HZ).max(0.0);
        let t = (d / (h - HZ)).clamp(0.0, 1.0);
        // fields: bands that widen toward us
        let band = (d.sqrt() * 2.1 + 0.6 * n.get(x * 0.3, d)).sin();
        let base = gradient(&[(0.0, hex("#7c7666")), (0.08, hex("#646152")), (0.3, hex("#4b4a3c")), (0.6, hex("#3c392f")), (1.0, hex("#2f2b24"))], t, Mix::Light);
        let tint = if band > 0.3 { shift(base, 0.012, -0.008, 0.01) } else if band < -0.5 { shift(base, -0.01, 0.005, -0.004) } else { base };
        // the glow still reaches the far meadows
        let g = (-((x - GX) / 300.0).powi(2)).exp() * (1.0 - smoothstep(0.0, 0.15, t));
        mix(tint, hex("#9d8c72"), g * 0.35, Mix::Light)
    };
    if o.stage("land", &mut c, &mut rng) {
        let far = land.clone().mul_fn(|_, y| 1.0 - smoothstep(HZ + 40.0, HZ + 60.0, y));
        let hd = st.body().color(land_look).angle(|_, _| 0.0).angle_jitter(0.04).curve(0.02, 0.1).length(12.0, 40.0).coverage(3.0).medium(0.3);
        c.work(&far, &hd, 51);
        let near = land.clone().mul_fn(|_, y| smoothstep(HZ + 35.0, HZ + 55.0, y));
        let hd = st.broad().tool(Tool { lay: 0.7, push: 0.05, ..Tool::filbert(14.0) }).color(land_look).angle(|x, y| 0.03 * n.get(x, y)).angle_jitter(0.06).length(35.0, 110.0).coverage(3.2).medium(0.25);
        c.work(&near, &hd, 52);
        c.dry();
    }

    // ---- the rise in front: one dark, strokes along its slope
    let rise = Mask::from_fn(f, |x, y| smoothstep(crest(&n, x) - 0.8, crest(&n, x) + 0.8, y));
    let rise_look = move |x: f32, y: f32| {
        let d = y - crest(&n, x);
        let top = 1.0 - smoothstep(0.0, 14.0, d);
        let base = mix(hex("#2c2821"), hex("#26221d"), smoothstep(40.0, 200.0, d), Mix::Light);
        mix(base, hex("#4a4133"), top * 0.6, Mix::Light)
    };
    if o.stage("rise", &mut c, &mut rng) {
        let slope = move |x: f32| {
            let e = 2.0;
            (crest(&n, x + e) - crest(&n, x - e)).atan2(2.0 * e)
        };
        let hd = st.body().tool(Tool { lay: 0.8, ..Tool::filbert(10.0) }).color(rise_look).angle(move |x, _| slope(x)).angle_jitter(0.12).length(20.0, 60.0).coverage(3.2);
        c.work(&rise, &hd, 61);
        c.dry();
        // dry grass on the crest, flicked up last: mostly dark blades, a
        // few catching the sky
        let tufts = Mask::from_fn(f, |x, y| {
            let d = y - crest(&n, x);
            (smoothstep(-2.0, 2.0, d) * (1.0 - smoothstep(10.0, 40.0, d))) * smoothstep(-0.2, 0.3, n.get(x * 3.0, 11.0))
        });
        let hd = st
            .detail()
            .tool(Tool::rigger(0.9))
            .color(|x, y| if n.get(x * 9.0, y * 9.0) > 0.45 { hex("#7a6a52") } else { hex("#2a251e") })
            .angle(|x, y| -FRAC_PI_2 + 0.35 * n.get(x * 5.0, y * 5.0))
            .angle_jitter(0.25)
            .length(4.0, 11.0)
            .coverage(0.9)
            .pressure(0.5, 0.8)
            .clip(false)
            .fill(false);
        c.work(&tufts, &hd, 62);
        c.dry();
    }

    // ---- the two figures on the rise, looking toward the town
    if o.stage("figures", &mut c, &mut rng) {
        let dark = pal.paint(hex("#1d1b19"), 0.05);
        let coat = pal.paint(hex("#2c2e2b"), 0.1);
        let hair = pal.paint(hex("#2a221c"), 0.1);
        let rim = Some(pal.paint(hex("#b79a78"), 0.2));
        let (fx, fy) = (772.0, crest(&n, 772.0) + 1.5);
        figures::man_in_cape(&mut c, (fx, fy), 70.0, coat, dark, hair, rim, 71);
        let g = Gown { dress: pal.paint(hex("#2d2826"), 0.1), shawl: Some(pal.paint(hex("#3b2f2a"), 0.1)), hair, skin: pal.paint(hex("#9a7f6a"), 0.1), rim };
        figures::woman(&mut c, (752.0, crest(&n, 752.0) + 1.5), 64.0, &g, WomanPose::Standing, 72);
        c.dry();
    }

    // ---- the last glaze, a shade deeper toward the edges (Friedrich to
    // Carus), an even film that wanders slowly
    if o.stage("glaze", &mut c, &mut rng) {
        let w = Fbm::new(91, 2, 500.0);
        let vig = Pigment::transparent(hex("#6b5a44"));
        c.glaze(&vig, None, move |x, y| {
            let dx = (x - GX) / 620.0;
            let dy = (y - HZ + 60.0) / 520.0;
            let r = (dx * dx + dy * dy).sqrt();
            (0.25 * smoothstep(0.35, 1.2, r) * (1.0 + 0.3 * w.get(x, y))).max(0.0)
        });
    }
    let _ = Held::new(Tool::round_sable(1.0), 0);
    let _ = rng.next_u64();
    o.finish(&mut c, &mut rng, &Finish::aged(st.relief));
}

