        let hd = st.body().tool(Tool { lay: 0.8, ..Tool::filbert(12.0) }).color(|x, y| shift(land_look(x, y), -0.03, 0.01, 0.0)).angle(|_, _| 0.0).cross(0.4).length(30.0, 80.0).coverage(2.6).medium(0.3);
